-- Generated by pnpm db:generate and changed by hand: the column is added
-- without NOT NULL, filled for the rows of 0003_device_description_tags.sql
-- and only then set NOT NULL. tags.name_key holds tagKey(name) of lib/tags.ts
-- (JavaScript toLowerCase); SQL can only fill existing rows with lower(name),
-- which equals it for the usual Latin and German letters, and every later
-- write sets the app's key. The old unique index on lower(name) guarantees
-- that these keys are unique per object, so the new unique index builds.
ALTER TABLE "tags" ADD COLUMN "name_key" text;--> statement-breakpoint
UPDATE "tags" SET "name_key"=lower("name");--> statement-breakpoint
ALTER TABLE "tags" ALTER COLUMN "name_key" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "tags" ADD CONSTRAINT "tags_name_key_check" CHECK (name_key<>'');--> statement-breakpoint
DROP INDEX "idx_tags_scope_name";--> statement-breakpoint
DROP INDEX "idx_tags_name_value";--> statement-breakpoint
CREATE UNIQUE INDEX "idx_tags_scope_name" ON "tags" USING btree ("scope_type","scope_id","name_key");--> statement-breakpoint
CREATE INDEX "idx_tags_name_value" ON "tags" USING btree ("name_key","value");
